import React from 'react';
import { Link, graphql } from 'gatsby';
import {
  Article,
  Content,
  Header,
  Layout,
  Pagination,
  SEO,
  SectionTitle,
  Wrapper,
} from '../components';
import config from '../../config/SiteConfig';
import Post from '../models/Post';

interface Props {
  data: {
    allMarkdownRemark: {
      totalCount: number;
      edges: Array<{ node: Post }>;
    };
  };
  pageContext: {
    currentPage: number;
    totalPages: number;
  };
}

export default function BlogTemplate({ data, pageContext }: Props) {
  const { currentPage, totalPages } = pageContext;
  const { edges, totalCount } = data.allMarkdownRemark;

  return (
    <Layout>
      <Header>
        <Link to="/">
          <strong>{config.siteTitle}</strong>
        </Link>
        <SectionTitle>전체 글 ({totalCount})</SectionTitle>
      </Header>
      <Wrapper>
        <Content>
          {edges.map(({ node }) => (
            <Article
              title={node.frontmatter.title}
              date={node.frontmatter.date}
              excerpt={node.excerpt}
              timeToRead={node.timeToRead}
              slug={node.fields.slug}
              category={node.frontmatter.category}
              key={node.fields.slug}
            />
          ))}
          <Pagination currentPage={currentPage} totalPages={totalPages} url="blog" />
        </Content>
      </Wrapper>
    </Layout>
  );
}

export const Head = ({ pageContext }: Props) => {
  const { currentPage } = pageContext;
  return (
    <SEO
      pathname={currentPage === 1 ? '/blog/' : `/blog/${currentPage}/`}
      title={`전체 글${currentPage > 1 ? ` ${currentPage}페이지` : ''} | ${config.siteTitle}`}
      description={`컴퓨터공학, 데이터베이스, 웹 개발과 오류 해결 글을 모은 목록${currentPage > 1 ? ` ${currentPage}페이지` : ''}입니다.`}
    />
  );
};

export const BlogQuery = graphql`
  query BlogPage($skip: Int!, $limit: Int!) {
    allMarkdownRemark(
      filter: { frontmatter: { draft: { ne: true } } }
      sort: { frontmatter: { date: DESC } }
      limit: $limit
      skip: $skip
    ) {
      totalCount
      edges {
        node {
          id
          fields {
            slug
          }
          frontmatter {
            title
            date(formatString: "YYYY-MM-DD")
            category
          }
          excerpt(pruneLength: 200)
          timeToRead
        }
      }
    }
  }
`;
